from fractions import Fraction

class VerificationError(Exception):
    pass

class Abort(Exception):
    pass

def ingest_pair(p):
    if not isinstance(p, list) or len(p) != 2:
        raise Abort()
    for tok in p:
        if not isinstance(tok, str):
            raise Abort()
        if not tok.lstrip('-').isdigit():
            raise Abort()  # rejects '0.5', '1e3', etc.: exact-rational-only ingestion
    num = int(p[0])
    den = int(p[1])
    if den == 0:
        raise Abort()
    return Fraction(num, den)

def ingest_term_list(lst):
    if not isinstance(lst, list) or len(lst) == 0:
        raise Abort()
    acc = Fraction(0)
    for t in lst:
        acc += ingest_pair(t)
    return acc

def verify_claim(c):
    if not isinstance(c, dict) or c.get('type') != 'linear_eq':
        raise Abort()
    lhs = ingest_term_list(c['lhs'])
    rhs = ingest_term_list(c['rhs'])
    if lhs == 0 and rhs == 0:
        raise Abort()  # trivial 0==0 claim: sign/content failure, fail closed
    return lhs == rhs

def verify(witness):
    """RAISES VerificationError on any failed check; returns True on full pass."""
    try:
        # 1) each batch claim must evaluate exactly as recorded
        for c in witness['claims_batch']:
            cid = c['id']
            if cid not in witness['expected']:
                raise VerificationError('unmatched claim id: %s' % cid)
            if verify_claim(c) != witness['expected'][cid]:
                raise VerificationError('exact-evaluation mismatch on %s' % cid)
        # 2) malformed input (float literal) must abort, not pass
        try:
            verify_claim(witness['malformed_input'])
            raise VerificationError('malformed input did not abort')
        except Abort:
            pass
        # 3) sign-failing (trivial 0==0) input must abort, not pass
        try:
            verify_claim(witness['sign_failing_input'])
            raise VerificationError('sign-failing input did not abort')
        except Abort:
            pass
    except Abort:
        raise VerificationError('unexpected abort inside batch phase')
    return True

WITNESS = {
    'claims_batch': [
        {'id': 'c1', 'type': 'linear_eq', 'lhs': [['2', '3'], ['-5', '7']], 'rhs': [['-1', '21']]},
        {'id': 'c2', 'type': 'linear_eq', 'lhs': [['1', '1']], 'rhs': [['3', '10']]},
        {'id': 'c3', 'type': 'linear_eq', 'lhs': [['-7', '9'], ['14', '3']], 'rhs': [['35', '9']]}
    ],
    'expected': {'c1': True, 'c2': False, 'c3': True},
    'malformed_input': {'id': 'c4', 'type': 'linear_eq', 'lhs': [['1', '0.5']], 'rhs': [['1', '2']]},
    'sign_failing_input': {'id': 'c5', 'type': 'linear_eq', 'lhs': [['0', '1']], 'rhs': [['0', '1']]}
}

assert verify(WITNESS) is True
